require_once __DIR__.'/config.php';require_role(['admin','hr']);$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT employee_no,first_name,last_name FROM employees WHERE id=?');$s->bind_param('i',$id);$s->execute();$emp=$s->get_result()->fetch_assoc();if(!$emp){http_response_code(404);exit('Employee not found');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$db->prepare('DELETE FROM employees WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'EMPLOYEE_DELETED','employee',(string)$id,'Deleted '.$emp['employee_no'].' '.$emp['first_name'].' '.$emp['last_name']);flash('Employee deleted.');header('Location: employees.php');exit;}
page_header('Delete employee');echo '<div class="card"><h1>Delete employee?</h1><p>Delete <strong>'.h($emp['employee_no'].' — '.$emp['first_name'].' '.$emp['last_name']).'</strong> permanently?</p><form method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><button class="danger">Confirm delete</button> <a class="btn muted-btn" href="employees.php">Cancel</a></form></div>';page_footer();